CREATE TABLE IF NOT EXISTS source_blocks (id INTEGER PRIMARY KEY, type TEXT NOT NULL, text TEXT NOT NULL, heading TEXT NOT NULL, line TEXT, topic TEXT NOT NULL, asset TEXT, alt TEXT, source_image TEXT, source_url TEXT NOT NULL, checksum TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS block_categories (block_id INTEGER NOT NULL REFERENCES source_blocks(id), category TEXT NOT NULL, PRIMARY KEY(block_id,category));
CREATE INDEX IF NOT EXISTS idx_blocks_line ON source_blocks(line);
CREATE INDEX IF NOT EXISTS idx_blocks_topic ON source_blocks(topic);
CREATE INDEX IF NOT EXISTS idx_categories_category ON block_categories(category,block_id);
CREATE VIRTUAL TABLE IF NOT EXISTS source_fts USING fts5(text,heading,topic,content='source_blocks',content_rowid='id',tokenize='trigram');
