INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (3,'li','生命靈數連線效應解析主要連線123－體能主線高頻狀態＝藝術線／獨立線低頻狀態＝任性線456－知能主線高頻狀態＝組織線／秩序線／治療線低頻狀態＝完美主義線／菲傭線／潔癖線456隱形連線補充說明=挫折線789－心靈主線高頻狀態＝權力線／貴人線低頻狀態＝懶人線／投機線7-8-9隱形連線補充說明=被動線159－成效主線高頻狀態＝事業線低頻狀態＝執著線、工作狂線159隱形連線=拖延線357－溝通主線 高頻狀態＝人緣線低頻狀態＝小人線／爭寵線／八卦線357隱形連線補充說明=懷疑線147－物質主線(身)高頻狀態＝務實線／安全線／錢財線低頻狀態＝貪財線／拜金線147隱形連線補充說明=混亂線258－情緒主線(心)高頻狀態＝感情線／表達線低頻狀態＝多嘴線／饒舌線258隱形連線補充說明=過度敏感線369/3690－創意主線(靈)高頻狀態＝智慧線／感情線／表達線低頻狀態＝空想線／作夢線／太空人線／任性小孩線3-6-9/3-6-9-0隱形連線補充說明=失憶線1590－因果主線（身1｜心5｜靈9｜宇宙0）高頻狀態＝修行線／超感知線／報恩線低頻狀態＝業債線／還債線／冤親債主線／敏感體質線主要修行數字次要修行數字小連線24連線高頻狀態＝靈巧線／變通線／應變線低頻狀態＝奸詐線／詭詐線／善變線26連線高頻狀態＝和平線／公平待人線低頻狀態＝不平衡線／利用他人線68連線高頻狀態＝親切誠實線／誠懇線低頻狀態＝虛偽線／隱瞞感受線48連線高頻狀態＝穩定線／勤勞線／工作模範線低頻狀態＝焦慮線／內心不安線特殊連線257－貴人數247－邏輯數246－安全感線269－愛心數235－桃花數','《生命靈數連線效應懶人包》連線對我們的命盤的影響非常大，空缺數的進階版，一定要存起來唷',NULL,'命盤算法與圈選','','','','https://amethyst100.com/connection-effect/','5df12038cc3cb4766ffdada822cf83268142531be59a0437a767e45a333b5db1');
