INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (49,'li','1代表獨創性的藝術喜好，喜歡獨一無二的特性。數字如果2圈以上，會比較有自己的主見與觀點，也希望保有自己的個人風格，常常是無師自通的特殊人才。','123－體能主線','123','藝術與獨立','','','','https://amethyst100.com/connection-effect/','39cfde7e593c12d3bae3bb574f22626dad7b4058262cddd9ffbc69eeef1445b1');
