INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (66,'li','6代表完美主義，雖然比較主觀，然而求好心切為所有數字中的第一名。完美相對之下就不見得能認同完整。因為完整是統合失敗與成功，完美只有成功。','456－知能主線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','37f1fdb00539451a69fa5ec4f16d13a5507b58971394828a7e8c51dfe066e1bb');
