INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (77,'li','456全缺者：把所有事情放在心理隱藏、容易讓人感覺陰沉。另外也成為隱性連線，在必要時特質才會顯現，甚至強過顯性連線。','低頻狀態＝完美主義線／菲傭線／潔癖線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','e0f7cfdfe59fda86f194e86cd148ad12d466f33f2ce61e261f4327fd5916b98e');
