INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (79,'p','在20世紀的前幾十年，這個隱形連線很罕見。然而，自1970年代開始，許多人的生命靈數命盤上出現了挫折線。挫折線的人通常表現出薄弱的意志，他們在家庭、人際關係和個人困惑方面面臨挑戰。','456隱形連線補充說明=挫折線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','93cc1dd33e70674adbf3ac6b35f48182dba6c85bc1bf66fe3b47cda5fef97135');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (79,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (79,'健康');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (79,'家庭');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (80,'p','挫折的真正含義是未能達成期望。擁有這條隱形連線的人常常期望他人超過他們願意提供的。然而，只要他們學會看到他人的真實和獨特之處，這種期望就會變得更合理。適度的期望更適合他們思考邏輯，可以讓他們接受最終的結果，視其為最佳選擇，而不會被情感所控制。也不會被事件的結果所束縛，而讓他人能夠做自己，而不只是他們期望的樣子。','456隱形連線補充說明=挫折線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','492490edcb8e0cc7e24aa4b219615db1a9e38f6b62661b6bd20b4b41468d35ca');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (80,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (80,'健康');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (80,'家庭');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (81,'p','擁有挫折線的人需要學會欣賞，因為這是最好的成長刺激物，但這種欣賞必須是真誠的，才能持久。要明白生活中的損失、分離和幻滅是邁向完美的旅程中的重要一步。隨著他們的覺察不斷增長，對他人的失望逐漸減少，並隨著智慧的成熟而消失。如果未能這樣做，他們將背負悲傷、孤獨和沮喪。隨著慈悲心的發展，他們將變得更快樂，明白早期挫折感只是童年時期的痕跡。','456隱形連線補充說明=挫折線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','ccb7188a9ce752878ef04bebece8b54dca57b62f39972da2b97a95e804d04f22');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (81,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (81,'健康');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (81,'家庭');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (82,'p','他們特別需要深層關愛，當他們因為他人的失望感到沮喪時，可能會覺得自己在生活中受到不公平對待。他們的情緒波動可能導致困惑和不安。父母應該教導他們接受他人的獨特性，不要期待他人應該要完全符合他們的期望，允許別人做自己。與父母建立深厚且敞開心胸的友誼關係對他們十分重要，這樣他們才能放心地交談，不會受到嚴厲批評或解釋的壓力，未來不管在感情上或職場上會有比較好的情緒控管能力。','456隱形連線補充說明=挫折線','456','組織與秩序','','','','https://amethyst100.com/connection-effect/','c1ba7e41bff7c0ed3f45b94749e0c48102092ff232e4746cb986279e4fb7da29');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (82,'事業');
