INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (86,'li','7代表福報貴人，所以貴人大多是來幫助你的，當然也有少數是來陷害你的。既然是福報，因此是前世因緣果報。要特別注意的是要學習感恩回報的態度，以及要懂得珍惜此機緣並且把握當下。','789－心靈主線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','0c17ba2835879a260bd7375cbe786aa740b976c34e9e46f387f79ce30398782c');
