INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (87,'li','8代表經營貴人，所以貴人是自己爭取努力經營而來的。這裡送禮物哲學成為人際關係的關鍵重點，溝通的語言藝術當然成為第二個關鍵重點。得知進退，拿捏尺寸，瀟灑得宜，當然能得外力而助己。','789－心靈主線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','91718187b07ba1671d75b97d38128a90339b213dc458cc8a9a6487408d94b342');
