INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (88,'li','9代表冤親貴人，乘著真正因果業力而來，能成就我們大智慧者。透過生命關係與互動，彼此得以消解前世業力。','789－心靈主線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','bba1fb4fb95628ab7e244b743c08f0ed87195b9d441185b44f44c4f14568379e');
