INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (91,'p','成就事業、個人魅力、掌控的力量、靈性特質、擁有對於成功事業的能量，所以並不是依靠努力打拼、賣力苦幹所得到的事業，而是利用發揮個人魅力的特質，讓客戶更容易因此而買單。有貴人幫助，有計劃、企圖心、智慧又有人脈，成就大事業是絕對的（無課題數前提之下）。','高頻狀態＝權力線／貴人線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','3328e6d658fa544ae36ae2bf04ffd25120a9bc665bbcb65fb1a04006fc8ecfdd');
