INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (93,'p','依賴性變高、惰性堅強、重投機性，時常太過依賴貴人的幫助，可能從身邊的親朋好友到互不相識的路人皆有可能，雖然會得到很多幫助，但由於太過於依賴他人，故會造成自身的惰性產生，即使事情發生也不會主動去處理，而是等其他人來幫忙，最後導致貴人遠離。','低頻狀態＝懶人線／投機線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','07f036258573dee6c4d8f0e43a4772e4af0eb9f718f708a7be3baed17d84342d');
