INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (97,'li','789全缺者：自己要成為自己的貴人，生活上比較不會有跟別人有過多的連結，此連線成隱性連線，在必要時特質才會顯現，甚至強過顯性連線。','低頻狀態＝懶人線／投機線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','788f5f4e901116a1dfd800c99e41ade6fffe5837b01d12ae2730629025e1bdfb');
