INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (99,'p','他們將成為新千年的思想家、策劃者和幕後導引者。然而，他們必須經過大量且持久的毅力訓練，才能真正取得成就，他們所具備的特質有助於減少戰爭和社會動盪，成就一個更和諧平衡的世界。','7-8-9隱形連線補充說明=被動線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','574e34ee61558b550543a9c5b8d16bcb63bf8689bcbf6a4492aada30017dcdcb');
