INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (101,'p','帶有這種隱形連線的小孩是需要受到鼓勵，並且更積極地參與日常活動。父母的鼓勵和參與對他們參與運動和活動的信心培養至關重要。與大自然共處也能對這類型的孩子人格發展帶來巨大好處。','7-8-9隱形連線補充說明=被動線','789','權力與貴人','','','','https://amethyst100.com/connection-effect/','8c8f3c2d1a47797f9d1396ef155040bf79f120c103d2949cb43302b2a0351fdd');
