INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (105,'li','1代表專心一致，全然地專注，尤其是讓它最有成就感與自我成就的事物。這個專注是理性的專注，在全然專注之時，心的作用停止了，所以能像瘋子一樣專心你所要成就的事務上。','159－成效主線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','2a2978f23c35891693bc64322db1ccddf37e4e24aa508a09b37344f8a012aa54');
