INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (106,'li','5代表有心要做的事物，有心能讓理性更專心，更有動能去做某件心想要完成的事物。','159－成效主線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','673ff8864ad1445590ac92427c6c8dea82a66ac286450c38eee28dc742148c4b');
