INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (107,'li','9代表美夢成真，讓夢想成真是一種身心靈統合之下的超然誘因。不只是理性或是心理慾望，它還帶著更脫俗更奧秘的未知動能，往某一個未知的領域前進摸索。','159－成效主線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','1add26b523947f71898a910607dc4686fb1e464902160f910df977b5ef4a6c91');
