INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (110,'p','堅持與熱情、全心全力投入事業當中，並把興趣融入其中、創造與持久力，不是靠企圖心去推動事業，而是對選擇的事業有興趣才會用心，持久的熱情去經營。要樂在工作、積極努力求上進。','高頻狀態＝事業線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','8bf6f5d2a9b6ed09b741f3dfabae6ef462d3c5400d994fb09622003e72e418dd');
