INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (112,'p','工作狂、偏執狂、執著於自我。太過投入，就會變成只想做自己想要做的事，而覺得其他事情不重要而忽略掉，不論只顧事業而不顧健康、不顧家庭、不顧感情等等。','低頻狀態＝執著線、工作狂線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','80d9ae1e0d56bf282e9bb9f8dba4627474213435c0f9229e0d2e4da81f42a6e4');
