INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (118,'p','通常這個從很小的時候就會發現這一個特徵，身為他們的父母必須要很有耐心與堅持來教會他們如何避免拖延或者擺爛，不能忽略任何可以教育他們面對這個課題的機會，否則成年後會容易有不守時、不守承諾、擺爛或三分鐘熱度的問題。在緊要關頭的時候，拖延線會使他們意識到事情的嚴重性，反而可以更有事業發展性與果斷策略能力。請記得沒有一個問題是不被重視的，如果今天是正確的結果，自然就不會產生問題，發現問題不能逃避，反而是要多利用自己現有的資源與智慧去思考如何解決問題，因為拖延只會讓幸福遲到。','159隱形連線=拖延線','159','事業與執行','','','','https://amethyst100.com/connection-effect/','257a9144084f83274b992d4277a0544c300ed9cf8023129f34b0fc2de8826716');
