INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (122,'li','3代表美麗人生，所以以第三者角色，或者以開心果的角色經營在人際關係信念之上，溝通能力強，所以常得人緣。','357－溝通主線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','e3ad45fdb105b527773ca7872558659ed19d5cf16934be2de55dfbad512e6c2b');
