INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (123,'li','5代表主動積極，自由自在所以讓人覺得比較沒有人情世故的壓力。而且主動積極的特性可以打破人際關係上的種種隔閡，極容易創造出全新的人際關係。然而喜新厭舊的特性使然，新朋友永遠比舊朋友多，人際關係能否密切而持續，得看靈數５的修養了。','357－溝通主線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','a8434d951ecbb292f61a3c00c3b65566523c5bfdc1010dfdeeecf6c565ff095e');
