INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (124,'li','7代表幽默歡笑而不容易生氣，常常疑神疑鬼，因為談吐幽默所以人際關係自然加成加分。','357－溝通主線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','6e94b295e96c5141964caa62d3841523519b5fd0d6ee26601004e4ce54874a5d');
