INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (125,'p','人際關係是需要用心經營的，投資管理若只是表面功夫而已，那麼一切的人際關係都只是一種假象，然而生命是一種假象，比較真實的卻是人際關係。','357－溝通主線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','2eae1f7523ac65a3530ed0875237313d8d69d9b5e7780fde5dbb0974a648c1cf');
