INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (127,'p','人緣佳、深受朋友、老闆、同事喜愛。展現自我、個人魅力、表現欲、適合擁有自己的舞台，口齒伶俐、敏捷的思維，擁有一定的幽默感，對於事情的看法有自我的主見，所以很難被忽略掉，自然擁有好人緣，但這並不是由於八面玲瓏、圓滑、善於交際、長得好看等因素，而是個人魅力的緣故。','高頻狀態＝人緣線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','e46e99da1751a99ce60530aacfc504522a040afe03aa52cd230e91e85c9fd157');
