INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (129,'p','愛爭寵、自我膨脹、耍大牌。很有吸引力，同時輕易地獲得好機會，所以常被別人稱讚與寵愛，但若讚美、溺愛過頭，就會容易利用該名氣的優勢來獲取更多愛戴，而造成自我膨脹、四處爭寵的情況當中。','低頻狀態＝小人線／爭寵線／八卦線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','83a52738022b2007e0ad86a71370d4cc25205d45511db5a253365ad6a88b48c2');
