INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (135,'p','他們常常對於任何新事物一開始都會抱持消極的態度，容易質疑別人，一旦認同又可能會盲目認同，有很多科學家有這一條隱形連線，他們不斷會去研究，將理論實踐化，反而是最讓他們自在的地方，對別人來說他們可能會比較沒有同情心，不太有愛的表現，其實只是他們覺得不值得去展現愛而已，不是不會，而是不想跟時機未到。','357隱形連線補充說明=懷疑線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','380dbe3830855371d96d3dd1803bcb391092d0e85965ebcdc3b6701ec5e8e238');
