INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (136,'p','但他們往往會比一般人對生命有更深的哲學體悟與理解。他們如果對生活的不確定感過強的話，容易出現憂鬱症，或者偏頭痛、眼壓高、耳石掉落等問題，只要涉及到擔心焦慮的事情，都會在他們的頭部有明顯的病症顯現，對待他們要充分的愛與仁慈，適時對他們的提問做出正確的反應，而不是漠視。','357隱形連線補充說明=懷疑線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','79f4d5d97f2a08f140d10e3210a04c52410bf4850e98bdb690c906be422f00b3');
