INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (137,'p','建議可多閱讀有關科學、自然、地理學等書籍，透過正確的調查事物因果方法，才能幫他們培養健康的好奇心，另外也可以透過藝術創作、音樂表演等方式來增強他們的自信，既有自己的小世界，也可以讓別人明白他們的真實感受。','357隱形連線補充說明=懷疑線','357','溝通與人緣','','','','https://amethyst100.com/connection-effect/','31a87feac2b1d9ac76f964ce713143749531e82e1414e9a09cbe88193ad0a945');
