INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (141,'li','1代表新物質的創造，只要是新奇的事物，都能引起數字1的注意力。因此他主要是以好奇心為主要動能，可是當他得力順手之時，就一直用到不行為止。靈數1也可以引申為最好的事物，第一名的事物，因此常常買到瘋狂的境界。此能量為開源型的能量趨向。','147－物質主線(身)','147','物質與安全','','','','https://amethyst100.com/connection-effect/','1259a83c9d44252250a7f4bad780ca1cf703d919a700937f8c72f26892f0c646');
