INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (142,'li','4代表節儉僅收型的能量，喜歡物美價廉，如果能免費得來更是佳美。善用他人資源，堅固保守自己資源到瘋狂的境地。雖然節儉但因固執重物質化，所以難免會有鐵公雞之嫌，但因重節流，所以困限於有限格局。','147－物質主線(身)','147','物質與安全','','','','https://amethyst100.com/connection-effect/','48643c14dcacb206176345c7eb2fdaac2c5ee07f0b9cd36099839cb870c588bb');
