INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (143,'li','7代表懶散擴張型的能量，常入不敷出，隨其心情喜怒為關鍵要素，常常自不量力，過度浪費而導致令人有率性之流氣。既能開源也能節流，然而意氣用事，喜歡玩樂，給人不紮實的感覺。','147－物質主線(身)','147','物質與安全','','','','https://amethyst100.com/connection-effect/','9d06eb6a690b5b13a89feb0bf7739982fd34973a8bd9edf6bff394361f4ce2b5');
