INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (155,'p','我們在地球上轉世的目的，是透過這片土地的能量振動，促進靈魂的成長，使其邁向更完美的發展。然而，對於那些出生圖中缺乏任何數字的人來說，這意味著他們將面臨著相當大的障礙，需要努力克服，才能在生活中找到一些程度的幸福。','147隱形連線補充說明=混亂線','147','物質與安全','','','','https://amethyst100.com/connection-effect/','bf6e9031cd71e540368f0704a7b5cdcbc245a7acf6769d0ce58039081bfe381a');
