INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (158,'p','兒童階段的他們需要父母的大力支持。培養務實性和整潔性是關鍵！他們需要學會一次完成一件事情，並在開始下一件之前先完成前一件。父母可以通過實用的遊戲和協助家務來與他們互動。為了鼓勵他們的努力，不僅需要口頭讚賞，更需要實際的認可，幫助他們培養平衡的唯物主義觀。隨著他們逐漸成長，參與非競爭性的體育運動和鍛鍊是很有幫助的，这些都將有助於培養他們的實際能力，進一步平衡他們的特質。','147隱形連線補充說明=混亂線','147','物質與安全','','','','https://amethyst100.com/connection-effect/','93f5bf0f802c63fe67db820ac03076e040a9387cf6501509d223f58e726d6468');
