INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (162,'li','2代表給予和分享，是表面上有目的性的，還是內心真實無私的分享？因為分享一詞在台灣幾乎快變成直銷、傳銷事業的專用語言了。如果是真情的分享，那一定是真情流露。','258－情緒主線(心)','258','情感與表達','','','','https://amethyst100.com/connection-effect/','94cd9b8576916bb8e6de7556ee10e19c5d6dd130ca433bd36a31f0221ca8a2e9');
