INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (163,'li','5代表主動積極侵入性的爆炸行為，它是由內心所發動。能從內心所發動的力量，自然有穿隧他人的作用。將心比心，這是一種全方位的同步作用，有時會比較希望他人能接受自己的企圖。','258－情緒主線(心)','258','情感與表達','','','','https://amethyst100.com/connection-effect/','76bad69f0f4b7cde48bb94dfdc3e0636ee1da6b5aae5f6a209ecbcdf275d8b0d');
