INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (164,'li','8代表進退得宜，除了保留靈數５的主動能量模式之外，它還會運用策略，以退為進的鯨吞蟬食的方式裂解對方，完成自己的企圖。','258－情緒主線(心)','258','情感與表達','','','','https://amethyst100.com/connection-effect/','aa55385c36dfa9ae2f0b8bdc11fa57a5e5dbb1515b2c8f9c26e16f9b2e99f1b2');
