INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (167,'p','活潑、能很快與人打成一片，善交際公關。情感真誠、與人聯繫強、健全的情感，除了男女情感方面，還包含了文字、音樂和藝術等領域方面的表達方式，外在上與其他人溝通能力較強，而內在則情感豐富、流露真誠。','高頻狀態＝感情線／表達線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','c6aafb09321060bab8c21b3c4970a487efc579d4f0b8ae9c2f844a96d7187cc9');
