INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (169,'p','說話傷人、恣意表達喜惡、禍從口出。想說就說、不思考表達時機，隨便恣意表達自己內心的喜惡，且口無遮攔的多嘴狀態，就會直接傷到其他人，也讓他人感到強烈的負擔及傷害。若擁有此連線又有6：容易有濫桃花氣場。','低頻狀態＝多嘴線／饒舌線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','b90bf4ce1a0b507c839556bf73d197733eb564f673c62d930bef2cc9f8bac819');
