INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (173,'li','258全缺者：在人群中表現較為安靜，但非常有人緣。此線若成隱性連線，在必要時特質才會顯現，甚至強過顯性連線。','低頻狀態＝多嘴線／饒舌線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','03d9344e29adc2286676666c8e697055fc2323bbf6fceb44211f7d713e4f4423');
