INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (175,'p','這條隱形連線會對他們帶來不同程度的情感問題，他們對自己的靈魂保護並不強，因此不管好壞他們總是第一時間有感覺，年輕時的他們還不太會掩飾自己的情感，會因為常常被冒犯而感到沮喪，反而漸漸不喜歡社交，變的非常害羞內向，早期產生的自卑感會讓他們在社會上遇到許多困難，嚴重時會失去對他人的信任，也容易患有被害妄想症，需要學會克服自己的情緒。','258隱形連線補充說明=過度敏感線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','752ab33bf35d875ea354ac20eaf2d3b33a493a4b24984f09db90be4b26a971ba');
