INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (176,'p','其實他們是有非常高能量的愛與溫柔的天性，但常因為過去創傷而築起高不可破的心牆，讓旁人看不懂他們的小劇場，而且他們在表達自己的感受時可能會具有歧視，總是對自己的愛情生活感到失望，但其實很多時候他們都是不對的在扭曲自己、嘲諷自己，有時候很固執，有時候又很大膽，但遇到感情問題就100%玻璃心，所以他們這一輩子需要認識自己的長板，並且利用這些長板來平衡自己的性格，在人生中實現某種程度的成就，當他們能夠被社會理解並且得到發展，就可幫助他們重建對人類的信仰與信心。','258隱形連線補充說明=過度敏感線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','a8cc0eacd2b6449e2faaac479b72d6e3795b83616ab93d3b1bf407eba4d6619d');
