INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (177,'p','他們小時候可能異常的害羞與敏感，尤其是對別人的聲音，容易緊張、驚嚇，所以他們會常常在公共場合低著頭，但其實只要身邊的人對他們可以多點耐心、關懷與善意，他們其實可以很輕鬆地被正確引導克服心魔，因為他們的焦慮、擔憂、恐懼，對於他們尚未成熟的頭腦而言是非常真實的，好好鼓勵他們說出自己的問題，幫助他們發展平和的情緒，產生勇於表達自己的安全感。','258隱形連線補充說明=過度敏感線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','a286d3fc4ef70f56ff8031346ed63c07b0c2269a95b603957708c3fd37a0d443');
