INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (178,'p','千萬不要當眾責罵與批評他們的錯誤，否則一定會加重他們的自卑感，應該帶他們到另一個有隱私的空間進行討論，才能幫助他們找到解決問題的最佳方法。','258隱形連線補充說明=過度敏感線','258','情感與表達','','','','https://amethyst100.com/connection-effect/','45cbfe2e38849f3fce1a6f99580a9e6a1d5f47904e72f18d3dea51bf538d4886');
