INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (182,'li','3代表提升進化，為突變昇華。透過語言的深層力量，以突顯出嶄新的真理。溝通與新觀念雖然都是一種提升，不過這些都是在訓練理性的知性區塊而已。因此觀音與文殊法門在此有它獨特的象徵定位，尤其是文殊菩薩是智慧的代表。靈數3需要透過知識的洗禮，得以跳脫出另外一個嶄新的格局架構。這裡從行動得到智慧。','369/3690－創意主線(靈)','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','53499d28c3a431cf3a0071c42f4d1193a784201cf29c147abc76c3d7c37b1223');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (182,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (182,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (183,'li','6代表慈悲喜捨，透過慈悲喜捨的互動模式，讓人以行動真正的遠離無知與假知。這是內心源泉以無私的精神去突破理性的限制，達到人類身心靈三方面徹底實踐的行動力。當一個人真正面臨無私無我的精神時，你的愛才會真正的湧現出來，愛不可能被創造出來，因為愛本身就是最初始的創造，愛在無始無明之時就被創造出來，不是這時候才被創造出來。','369/3690－創意主線(靈)','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','4a1c3fcb9212c655404b0168f23bd50b998ed3e001c3dc20d0bfb42baa660809');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (183,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (183,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (184,'li','9代表集體無意識的智慧，透過宗教與神祕學的洗禮，得以淬鍊出無意識的智慧精華出來。9是腦神經系統與潛意識系統的通稱，有人說是神通能力，不過它確實是腦部的另類傑作。在腦神經寂靜之時，它便可以接收及傳輸潛意識的訊息與智慧。','369/3690－創意主線(靈)','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','0e4828dc32e5f337762702a76ee55b1674a6f286f2c7ea1c674a00cd6f923f8c');
