INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (185,'p','透過語言3，行動6，或是禪定9我們都可以找到我們要的直覺智慧，只是誘導出智慧的方式不同罷了。','369/3690－創意主線(靈)','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','f10e053b0c737adea5f1c9df4881e19434ddf07dbfbd0dc33943f3189717678e');
