INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (187,'p','聰明伶俐、表達力佳，很適合從事講師的工作。有智慧、具靈性、多悟性、神性思維。是走向智慧的途徑，智慧並不是表面的聰明機智而已，也不是刻苦學習、發憤圖強就能夠達到的，而是精神層面的思考、層次與悟性。擁有此線又有先天數6：容易有桃花氣場。','高頻狀態＝智慧線／感情線／表達線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','1b5cd4f361d9c6be781f7911d43d0a0867a8661c3000f4f0aaa49c50c3f0d732');
