INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (189,'p','空想、不切實際、思考而不行動。若思考多於行動的話，也會變成思想的桎梏。','低頻狀態＝空想線／作夢線／太空人線／任性小孩線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','d6b1583818e2c4671460d8f4442accecc3edbedcd8b22add2269c5e93384b1f2');
