INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (192,'li','連線缺9者：做事了草、馬虎，會忘記執行的意義與初衷。','低頻狀態＝空想線／作夢線／太空人線／任性小孩線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','a706af8bd52431cb12970ac2ab880015d91f90d7dee4d9d28f82f3cb86faba5d');
