INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (193,'li','缺369者：對生活比較沒有什麼想法，可能對靈性話題沒有話題，無神論者，對於自己未來也不會有太多的期望與願力，此線成隱性連線，在必要時特質才會顯現，甚至強過顯性連線。','低頻狀態＝空想線／作夢線／太空人線／任性小孩線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','9cdfaf43688af99fa74bfb7c4d5b0de89e0bfdd68ede2eabaee8b3469d7f1172');
