INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (195,'p','沒有智慧線的人，不代表不會思考，而是他們會要保持記憶力的活躍，一旦開始懶惰，不想記取更多的東西，那敏銳度會迅速下降，嚴重則在中年初期就會出現癡呆或者延伸出阿茲海默症等問題，如果出現學習遲緩的狀況，一定盡快就醫。','3-6-9/3-6-9-0隱形連線補充說明=失憶線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','705b0b6440c2a612364257f13f26c2de329ccf7ed16c498bb060e4fe99f6b4c1');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (195,'事業');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (195,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (196,'p','雖然他們在外人面前大多都感覺很聰明與機智，這是因為他們沒有放棄觀察，還有去體驗人生，願意去克服障礙。一般他們在嬰兒時期的智力表現會比較緩慢，就一定要加強訓練以增加專注力，這對他們的記憶力會有很大的影響，另外可以透過藝術和大自然的感知訓練去拓展他們創造力，這絕對對他們的心智成長有大作用，建議不要太早讓他們接受學術的培訓，若過去強迫他們學習，或者過分要求成績，都會導致他們出現頭痛問題，反而可能會讓病症耽誤學業。','3-6-9/3-6-9-0隱形連線補充說明=失憶線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','b276a17d10c0669002030e9deb453b451446b77a23736bd28a95fa227afdb1eb');
