INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (197,'p','建議6歲後再接觸正式的教育體系會比較好，還有對他們最好的教育方式就是接觸大自然，因為他們對大自然的探索會比科學理論有興趣多，因此他們文科、理科沒有出色的表現也是正常的。','3-6-9/3-6-9-0隱形連線補充說明=失憶線','369','智慧與創造','','','','https://amethyst100.com/connection-effect/','85db393e0e3583ae4a26b0e1dde33500d20697230eb0c4f0a4edd569e49f855c');
