INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (201,'li','這輩子專注一件事情就好，就是「修行」。','1590－因果主線（身1｜心5｜靈9｜宇宙0）','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','89fb9d99ad7a430f5349c82d6ba681fc950d4a1c8a4c6d4e830857e60d6fe83f');
