INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (202,'li','這輩子必須專心”修行”，表示有前世因果輪迴課題要學習。','1590－因果主線（身1｜心5｜靈9｜宇宙0）','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','877443df55d97b55eac6bb254a1497ca7974ede84e0f94309e7195131b48c218');
