INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (203,'li','靈體較敏感，要做好保護措施才不會受到無形干擾，需更了解自己此生的任務卷軸，並且努力執行。小心邪魔歪道、誤入歧途。','1590－因果主線（身1｜心5｜靈9｜宇宙0）','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','5060b261f9f62d731c4c69f8265c88c657fe225bf43daca495bcd6b268152d24');
