INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (205,'p','前世可能有修行並供養過許多揚升大師，或者對地球或對外星文明有做過貢獻，因為願力、約定、任務等等再接續到此世繼續修行，好好運用自身的超感知力，能幫助自己化險為夷，也能參透別人的因果業力。','高頻狀態＝修行線／超感知線／報恩線','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','2babd0d13a758063b9a7ed2c1ccfae5e25b44bd6d4c71a6768d1050da979ae3b');
