INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (207,'p','不相信鬼神因果，小時候脾氣暴躁、過分調皮，總是讓父母操心，成長過程中總是遇到許多障礙，頻率低時更容易被邪魔附身，導致做出無法意料的傷害自己或他人行為，常被無形干擾而無法正常生存在社會當中。','低頻狀態＝業債線／還債線／冤親債主線／敏感體質線','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','3af7ad0b598fc8d8188ac37c830be38427f657399ff0e07f6b38fa520892f813');
