INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (208,'p','可以透過課題數、或哪一個靈數圈數較多，可以判斷此生因果課題的主要修行方向。','低頻狀態＝業債線／還債線／冤親債主線／敏感體質線','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','71867dfac145acc0593e39f165b286ca48789fd4da444864893c2eeea58cccdb');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (208,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (209,'h6','主要修行數字','主要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','b1d3212639ce4a4c23c67b7cc17fe1d7ec7238689592041074b65a577b024c60');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (209,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (210,'p','當課題數在靈數1的時候（1為天賦數或主命數)

課題數在1的修行方式就是認識自我，因為靈數1考驗著自我心智的成熟度，無關乎宗教。如何讓自我心智與意識形態轉變成智慧的波能才是修行的主體。知識是未加工前的智慧半成品，自我需要透過生命事件的挫折中去累積一點一滴的智慧。理智經過嘗試、歷練、沉澱、辯證、覺知，取捨後才得以加工成為智慧，智慧是理性的知識成品，是經過琢磨修飾後的藝術傑作。大乘佛教有以唯識論為辯證基礎，討論意識範疇有著相當豐富的經典論述，常人說：佛渡有緣人，所渡者，人之意識罷了。','主要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','737bda34e9bd2878b71a9c46d1b4fce3068bf0da014a9031e88b5acf06f5cb6d');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (210,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (211,'p','當課題數在靈數5的時候（5為天賦數或主命數)

課題數在靈數5的功課是認識自心，修行觀自在菩薩，自性佛的修練法。５是個修習內在深層心靈，如何讓神光自由自在的透射出來，這就是所謂的時空之大自在覺者。所有心靈知識的終極目的是再回歸力量的源頭。其中一個目的是說服你自己，如何誠實地面對自己心靈的恐懼與內疚，了解這個世界不過是我們心念所投射的一個幻象世界而已。藉此觸探自我深層的神性，見證它的現身。我們最終都必須獨自面對自己不可思議神智的化現與奇蹟，認識而運用它，我們將發現到這一體的無上秘密，愛的語言行動與上帝的精神。神人合一喜悅，將讓你有超越及深入世間法之自由自在的價值觀。這種修習方法，需要有創意的去體驗自己，將警覺性放在心識與心法上的進步。','主要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','c9657970a36ce0434220e9476a5f77da78e3554b0b34a19972d06ef783596725');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (211,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (212,'p','當課題數在靈數9的時候(9為天賦數或主命數)

課題數在靈數９，表示這一世主修的宗教修行，要學習如何在縱慾與斷慾之間的神聖平衡！在犧牲自己，成全他人與成就自我之間找到平衡之道。生命自然有祂神奇的安排處！至少要起碼兩種以上的宗教，你該認真地去學習與體驗，如此你才能對比分類出異中求同的奧秘。找出你喜歡，以及與你有緣的宗教吧！跟隨它，讓這個嚮導帶領你去探索這不可思議的世界吧！','主要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','6a653ad55e1723e25a3d71a554bb33294b6c7ce615dc6c8bb5b9431175978b35');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (212,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (213,'p','當課題數在靈數0的時候(0為天賦數)

０就是大自然、宇宙、時空與生活中的一切，如何從日常生活中每一個際遇，每一個邂逅中了解宇宙時空的本質與訊息。每一個自我劇情背後所隱藏的真理祕義，你能夠一眼看穿它嗎？你能夠將它導引為自我成長力量嗎？

活在每一個當下的警覺性與自我反照，正就是靈數０學習訓練自我智慧最佳時刻！主命數是整數人（10/1）修行是大自然的修法，無時不修、無處不修，從體驗及觀察宇宙萬物的互動去實踐與見證真理。','主要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','ad890f9f3360793589bce955b4c1955cac922cb6c3b7dd5a97e496e5c9323866');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (213,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (214,'h6','次要修行數字','次要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','77899fffb2e48cdcdf49b0eae54352602d9c75a03a9fbb63a0efea4a3caaf826');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (214,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (215,'p','當課題數在靈數7的時候(7為天賦數或主命數)

課題數在靈數７的人修行的是主修世間一切萬物的真理，尤其是知識上的真理，要如何轉變成智慧之光。相信並認同你的求知慾，也要有身體力行的決心才行，開放你的能量場有加速你的自我的轉化與精進。','次要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','1bc86520f3e336ecaec485cba0b3a6d34bba336b9b97c411543a4aff90170883');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (215,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (216,'p','當課題數在靈數2的時候(2為天賦數或主命數)

課題數在靈數２的修行方式就是直接嘗試，並學習神聖的平衡，學習真假的分辨，真理是近化中相對的統一性。所以請讚嘆這相對的統一性，因為它能窺探絕對的虛空本體。寬恕自己在紅塵世界的每一場生命都只是一場遊戲罷了，如此一切終將消解。這不是終極的秘密，但它的確是最終極的行動，那融入一體的奧秘，是將小我與上主之間的鴻溝與對立全部消弭掉。','次要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','4dcfd6249892329ff5016f3a9436d8e96f487bae39c7b77592f27c990c0f623f');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (216,'健康');
INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (217,'p','當課題數在靈數3的時候(3為天賦數或主命數)

課題數在靈數３的修行方式，一開始是從人際關係中學習溝通，再利用語言行動上的不可思議性的動能，來刺激自我新的思考方向，這種以語言我（形式我）為師的訓練，其目的就是找尋嶄新的價值觀，讓自我可以解構再重構，不固執任何成見與模式，因此自我心智得以迅速地成長與近化。要學習轉苦為樂，化醜為美的意念轉變地功夫，超越傳統的價值與觀念。建議要多與人溝通，從語言中我們將運用更實在的主體本質性，投射更直接的真理性訊息，我們將發現我不是那麼狹小，我就是我生命中的巨人。','次要修行數字','1590','業力與課題','','','','https://amethyst100.com/connection-effect/','b2ff68040486480ed486860f17965f4ebc28b6cd6bd97ea483b83e7a4f71f522');
INSERT OR IGNORE INTO block_categories (block_id,category) VALUES (217,'健康');
