INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (235,'li','2代表平等和諧，然而2蠻靠近靈數1，因此唯有深度內化的高階靈數1才會讓靈數2展現真正的平等與和諧。其他層次的靈數2多少還是保有靈數2的自我重要感的能量跳脫進來的危機，讓靈數2變得比較為自己而思考。','26連線','26','和平與公平','','','','https://amethyst100.com/connection-effect/','b556fcb941c499f9c71c2d005280f195a1ca629464bfc79d830736b5200f1836');
