INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (236,'li','6代表本身一昧地照顧他人，所以在自我與他人的能量工書上，比較會選擇成就他人。然而當靈數６在低頻的時候，可能會比較偏向於自己，而認為所做的犧牲都是白費的。','26連線','26','和平與公平','','','','https://amethyst100.com/connection-effect/','bdfa4b32deed95c4257e4cf7ddbe86d8e8a430b4aadc652a49289cadc50d8d74');
