INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (261,'li','4代表穩定踏實，認真負責，自然成為工作的模範生，然而靈數4也是安全與防衛型的思考模式，不容易將內心的不安表達出來。','48連線','48','穩定與責任','','','','https://amethyst100.com/connection-effect/','69bf790fac5483c709e60c6f600b794982a8b1cfa332bbead6a3edf0809696d5');
