INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (262,'li','8代表2*4=8，本身已含靈數4的能量特性。8比4還要更深層與內化，在長期的計謀策略之中，短期的工作表現並不能代表他的一般工作水準，也更不容易將他內心的憂慮與煩惱分享給他人知道。','48連線','48','穩定與責任','','','','https://amethyst100.com/connection-effect/','0ff4809de9b8712ea750a0288102fda8a9092ecfbe6557cfa74b476ccca275a6');
