INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (292,'p','當連線處於高頻能量時，大滿貫，能力強、吸收力快，代表具備非常多項地能力特質，學習任何領域都特別快，心思也較複雜，這樣的人通常很機智、聰明、興趣涉獵很廣泛。','全連線或4條以上連線',NULL,'連線數量與總結','','','','https://amethyst100.com/connection-effect/','95fa4964fa40213919557ad0f4a47e9fa9a1315720674812068228285c64625c');
