INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (293,'p','當連線處於低頻能量時，目標或方向不明確、無法抉擇。容易被原生家庭、朋友引導。有時會造成自身的矛盾，也不知道自己應該專注於哪一項特質，擁有所有的特質卻又沒達到自己的要求反而會挫折感特別重，同時也不知道應該往哪個方向發展，不確定哪個才是真正喜歡或不喜歡，學什麼都快卻難以抉擇哪個才是最好的。','全連線或4條以上連線',NULL,'連線數量與總結','','','','https://amethyst100.com/connection-effect/','2bd0d2b20a3274db0527d05f8b6c4beb67d78778300e37a8b0bebdff5a0a19da');
