INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (298,'p','高頻能量時可塑性高、特長明確，對自己的目標、方向、喜好等有非常清楚的理解與看法，連線越簡單代表個性可能也越單純，個人特質上的矛盾也相對越少，同時效率也可能越高，也由於特質相對較少，所以可塑性會比較高。','沒有連線或2條以下連線',NULL,'連線數量與總結','','','','https://amethyst100.com/connection-effect/','6f061d83ff484f313046325c8a233401d0a8c46fe398265870691c5c9455ccb0');
