INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (299,'p','低頻能量時學習較辛苦、不擅長的地方多，較能專注一個特長，對於不擅長領域則需要花費更多的時間和力氣去學習，才可以補足這些不擅長的地方。','沒有連線或2條以下連線',NULL,'連線數量與總結','','','','https://amethyst100.com/connection-effect/','aa8e36125e96b827950dd741296ccb0556fedd97f6d10dc10734a11c9a082b06');
