INSERT OR REPLACE INTO source_blocks (id,type,text,heading,line,topic,asset,alt,source_image,source_url,checksum) VALUES (301,'p','以上這些連線解析並非絕對，畢竟一個人的命盤會有很多可能，請不要太過於執著或焦慮，應該要能夠看到這些連線時要提醒自己保有高頻的狀態即可，畢竟每個人的命盤與課題不同，因此如果想了解更符合你的狀況，還是建議要另外跟儷兒老師預約諮商會比較能夠幫助你釐清問題，並且找到適合自己面對自身任務卷軸的方式唷！','沒有連線或2條以下連線',NULL,'連線數量與總結','','','','https://amethyst100.com/connection-effect/','0e2491fac71102782b65234578f82fab0fbf7a5e046e5e948e86fcff7e4a78d7');
